from collections import Counter

def solve(n, arr, x):
	positions = set()
	for i in range(x.bit_length()):
		if x & 1 << i > 0:
			positions.add(i)
	lookup = Counter()
	res = 0
	for num in arr:
		required = []
		for i in range(30):
			if i in positions:
				if num & 1 << i > 0:
					required.append(1)
				else:
					required.append(0)
		required = tuple(required)
		res += lookup[required] * 2
		lookup[required] += 1
	return res + n
for _ in range(int(input())):
	n = int(input())
	arr = list(map(int, input().split()))
	x = int(input())
	print(solve(n, arr, x))
